text:
.attachmentList {
  appearance: none;
  -moz-user-focus: normal;
  margin: 0;
  padding: 3px;
  background-color: var(--layout-background-2);
  color: var(--layout-color-2);
  border: none;
  display: flex;
  overflow-x: hidden;
  align-items: start;
  align-content: start;
  flex: 1;
  flex-direction: row;
  flex-wrap: wrap;

  &[collapsed] {
    display: none;
    block-size: 0;
  }
